//! Runs: executions pinned to the Version they started on (ADR-0009), and their Checkpoints.

use std::fmt;

use bia_core::dsl::WorkflowId;
use chrono::{DateTime, Utc};
use serde_json::Value;
use sqlx::PgConnection;
use sqlx::types::Json;
use uuid::Uuid;

use crate::StoreError;
use crate::versions::{self, VersionNumber};

/// A Run's id, generated by the store.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct RunId(Uuid);

impl RunId {
    pub fn from_uuid(id: Uuid) -> Self {
        Self(id)
    }

    pub fn as_uuid(self) -> Uuid {
        self.0
    }
}

impl fmt::Display for RunId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.fmt(f)
    }
}

/// Where a Run is in its lifecycle: `pending → running → (sleeping | waiting) → running →
/// succeeded | failed | cancelled`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum RunStatus {
    Pending,
    Running,
    Sleeping,
    Waiting,
    Succeeded,
    Failed,
    Cancelled,
}

impl RunStatus {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Pending => "pending",
            Self::Running => "running",
            Self::Sleeping => "sleeping",
            Self::Waiting => "waiting",
            Self::Succeeded => "succeeded",
            Self::Failed => "failed",
            Self::Cancelled => "cancelled",
        }
    }

    /// Whether the Run has ended.
    pub fn is_finished(self) -> bool {
        matches!(self, Self::Succeeded | Self::Failed | Self::Cancelled)
    }

    fn from_db(status: &str) -> Result<Self, StoreError> {
        Ok(match status {
            "pending" => Self::Pending,
            "running" => Self::Running,
            "sleeping" => Self::Sleeping,
            "waiting" => Self::Waiting,
            "succeeded" => Self::Succeeded,
            "failed" => Self::Failed,
            "cancelled" => Self::Cancelled,
            other => return Err(StoreError::invalid("run status", other)),
        })
    }
}

/// The persisted state of a Run after a transition. The interpreter owns what goes inside.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct Checkpoint {
    /// The Cursor: a path through nested Blocks, one segment per level.
    pub cursor: Vec<Value>,
    /// Everything else the interpreter needs to resume.
    pub state: Value,
}

/// One execution of a Version.
#[derive(Debug, Clone, PartialEq)]
pub struct Run {
    pub id: RunId,
    pub workflow_id: WorkflowId,
    pub version: VersionNumber,
    pub status: RunStatus,
    pub input: Value,
    /// What started the Run, readable as `trigger` in Expressions.
    pub trigger: Value,
    pub checkpoint: Checkpoint,
    pub created_at: DateTime<Utc>,
    pub updated_at: DateTime<Utc>,
    /// When the Run reached a finished status.
    pub finished_at: Option<DateTime<Utc>>,
}

/// A `runs` row as read back from Postgres.
struct RunRow {
    id: Uuid,
    workflow_id: String,
    version: i32,
    status: String,
    input: Value,
    trigger: Value,
    cursor: Json<Vec<Value>>,
    state: Value,
    created_at: DateTime<Utc>,
    updated_at: DateTime<Utc>,
    finished_at: Option<DateTime<Utc>>,
}

impl TryFrom<RunRow> for Run {
    type Error = StoreError;

    fn try_from(row: RunRow) -> Result<Self, StoreError> {
        Ok(Self {
            id: RunId(row.id),
            workflow_id: WorkflowId::new(row.workflow_id)
                .map_err(|err| StoreError::invalid("workflow id", err))?,
            version: VersionNumber::from_db(row.version)?,
            status: RunStatus::from_db(&row.status)?,
            input: row.input,
            trigger: row.trigger,
            checkpoint: Checkpoint {
                cursor: row.cursor.0,
                state: row.state,
            },
            created_at: row.created_at,
            updated_at: row.updated_at,
            finished_at: row.finished_at,
        })
    }
}

/// What a new Run starts from.
#[derive(Debug, Clone, PartialEq)]
pub struct NewRun {
    pub workflow_id: WorkflowId,
    /// The Published Version the Run is pinned to for its whole life.
    pub version: VersionNumber,
    pub input: Value,
    pub trigger: Value,
    pub checkpoint: Checkpoint,
}

/// Creates a `pending` Run at `at`, pinned to a Published Version.
pub async fn create(
    conn: &mut PgConnection,
    run: &NewRun,
    at: DateTime<Utc>,
) -> Result<Run, StoreError> {
    let row = sqlx::query_as!(
        RunRow,
        r#"
        INSERT INTO runs (workflow_id, version, status, input, trigger, cursor, state, created_at, updated_at)
        SELECT v.workflow_id, v.number, 'pending', $3, $4, $5, $6, $7, $7
        FROM versions v
        WHERE v.workflow_id = $1 AND v.number = $2 AND v.state = 'published'
        RETURNING id, workflow_id, version, status, input, trigger,
                  cursor AS "cursor: Json<Vec<Value>>", state, created_at, updated_at, finished_at
        "#,
        run.workflow_id.as_str(),
        run.version.get(),
        run.input,
        run.trigger,
        Json(&run.checkpoint.cursor) as _,
        run.checkpoint.state,
        at,
    )
    .fetch_optional(&mut *conn)
    .await?;

    match row {
        Some(row) => Run::try_from(row),
        None => Err(versions::why_not_published(conn, &run.workflow_id, run.version).await?),
    }
}

/// Reads one Run with its Checkpoint.
pub async fn get(conn: &mut PgConnection, id: RunId) -> Result<Option<Run>, StoreError> {
    let row = sqlx::query_as!(
        RunRow,
        r#"
        SELECT id, workflow_id, version, status, input, trigger,
               cursor AS "cursor: Json<Vec<Value>>", state, created_at, updated_at, finished_at
        FROM runs
        WHERE id = $1
        "#,
        id.0,
    )
    .fetch_optional(&mut *conn)
    .await?;

    row.map(Run::try_from).transpose()
}

/// Records a transition at `at`: the Run's new status and Checkpoint. A finished status also
/// sets `finished_at`.
pub async fn update_checkpoint(
    conn: &mut PgConnection,
    id: RunId,
    status: RunStatus,
    checkpoint: &Checkpoint,
    at: DateTime<Utc>,
) -> Result<(), StoreError> {
    let finished_at = status.is_finished().then_some(at);
    let updated = sqlx::query!(
        r#"
        UPDATE runs
        SET status = $2, cursor = $3, state = $4, updated_at = $5, finished_at = $6
        WHERE id = $1
        "#,
        id.0,
        status.as_str(),
        Json(&checkpoint.cursor) as _,
        checkpoint.state,
        at,
        finished_at,
    )
    .execute(&mut *conn)
    .await?
    .rows_affected();

    if updated == 0 {
        return Err(StoreError::RunNotFound(id));
    }
    Ok(())
}

/// Which Runs [`list`] returns.
#[derive(Debug, Clone, PartialEq)]
pub struct RunFilter {
    pub workflow_id: Option<WorkflowId>,
    pub status: Option<RunStatus>,
    /// Only Runs listed after this one, for paging.
    pub after: Option<RunId>,
    pub limit: u32,
}

impl Default for RunFilter {
    fn default() -> Self {
        Self {
            workflow_id: None,
            status: None,
            after: None,
            limit: 50,
        }
    }
}

/// Lists Runs newest first.
pub async fn list(conn: &mut PgConnection, filter: &RunFilter) -> Result<Vec<Run>, StoreError> {
    let rows = sqlx::query_as!(
        RunRow,
        r#"
        SELECT id, workflow_id, version, status, input, trigger,
               cursor AS "cursor: Json<Vec<Value>>", state, created_at, updated_at, finished_at
        FROM runs
        WHERE ($1::text IS NULL OR workflow_id = $1)
          AND ($2::text IS NULL OR status = $2)
          AND ($3::uuid IS NULL OR (created_at, id) < (SELECT created_at, id FROM runs WHERE id = $3))
        ORDER BY created_at DESC, id DESC
        LIMIT $4
        "#,
        filter.workflow_id.as_ref().map(WorkflowId::as_str),
        filter.status.map(RunStatus::as_str),
        filter.after.map(|id| id.0),
        i64::from(filter.limit),
    )
    .fetch_all(&mut *conn)
    .await?;

    rows.into_iter().map(Run::try_from).collect()
}
